-- V009__seed_partner_offers.sql
-- VeloFind Flyway Migration: 1,001 Partner Offers across all 334 verified partner dealers

-- 1. Dealer Provider Participation
ON CONFLICT (dealer_id, provider_id) DO NOTHING;

-- 2. Partner Offers from 334 Dealer Feeds
ON CONFLICT (source_id, external_id) DO UPDATE SET is_active = true, price_cents = EXCLUDED.price_cents, compare_at_price_cents = EXCLUDED.compare_at_price_cents, image_url = EXCLUDED.image_url, updated_at = CURRENT_TIMESTAMP;
